const ts = i => props(i.json)["Timestamp"]?.date?.start || i.json.created_time;
const rows = $input.all().filter(i=>i.json.id).sort((a,b)=>new Date(ts(a))-new Date(ts(b))).slice(-25)
 .map(i=>({ t: new Date(ts(i)).toLocaleTimeString("en-US",{hourCycle:"h23",timeZone:"America/New_York"}),
